// The page's forward kinematics over the structure's `kinematics` block: `__fixtures__/hinge` is a
// served document as `cadgen xbf serve` answers it for a two-part revolute hinge (a base, and an
// arm on joint `elbow` through (40, 0, 20) along +Y, range -10..120, connected at 30, with
// configurations `raised` (90) and `flat` (0)). It is regenerated by building that model (the
// engine's kinematics test, `HINGE`) and saving `GET /api/doc/<id>` and each part.
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";
import * as THREE from "three";

import { createXbfScene } from "./xbfScene.js";
import { xbfKinematics, xbfLinkPlacements, xbfOtherWarnings, xbfPoseControls, xbfPosedMatrices, xbfPoseValues } from "./xbfKinematics.js";
import { readXbmPart, xbmUnmeshedFaces } from "./xbm.js";

const FIXTURE = path.join(path.dirname(fileURLToPath(import.meta.url)), "__fixtures__", "hinge");
const STRUCTURE = JSON.parse(fs.readFileSync(path.join(FIXTURE, "structure.json"), "utf8"));
const ARM = 1;

/** The arm's corner (120, 10, 10) of its own frame at elbow `q`, in closed form (the engine's test's). */
function armTip(q) {
  const s = Math.sin(q * Math.PI / 180), c = Math.cos(q * Math.PI / 180);
  return [40 + 120 * s + 10 * c, 10, 20 + 120 * c - 10 * s];
}

const place = (m, p) => [0, 1, 2].map(row => m[row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2] + m[12 + row]);
const near = (actual, expected, what) => actual.forEach((value, at) => assert.ok(Math.abs(value - expected[at]) < 1e-9, `${what}: ${actual} != ${expected}`));

test("forward kinematics from the block places the arm where the closed form says", () => {
  const kinematics = xbfKinematics(STRUCTURE);
  assert.equal(kinematics.pairs[0].type, "revolute");
  assert.deepEqual(kinematics.links.map(link => link.instances), [[0], [1]]);
  // As built, the structure's own matrices.
  const asBuilt = xbfPoseValues(kinematics);
  assert.deepEqual(asBuilt, { elbow: [30] });
  near(place(xbfPosedMatrices(STRUCTURE, asBuilt)[ARM], [120, 10, 10]), armTip(30), "as built");
  for (const [pose, q] of [["raised", 90], ["flat", 0], [{ elbow: -10 }, -10], [{ elbow: 75 }, 75]]) {
    const matrices = xbfPosedMatrices(STRUCTURE, xbfPoseValues(kinematics, pose));
    near(place(matrices[ARM], [120, 10, 10]), armTip(q), JSON.stringify(pose));
    assert.deepEqual(matrices[0], STRUCTURE.instances[0].matrix, "the ground stays");
  }
  // The links' placements compose: the ground where it is, the arm's frame on it.
  const [ground, arm] = xbfLinkPlacements(kinematics, { elbow: [30] });
  assert.deepEqual(ground, kinematics.links[0].matrix);
  near(arm, kinematics.links[1].matrix, "the arm's frame as built");
});

test("a pose naming a joint wrong, or a value out of range, is refused by name", () => {
  const kinematics = xbfKinematics(STRUCTURE);
  assert.throws(() => xbfPoseValues(kinematics, { elbw: 1 }), /names no joint 'elbw'/);
  assert.throws(() => xbfPoseValues(kinematics, { elbow: 150 }), /'elbow' at 150 deg is outside its range \[-10, 120\]/);
  assert.throws(() => xbfPoseValues(kinematics, "folded"), /no configuration 'folded'/);
  assert.throws(() => xbfPoseValues({ ...kinematics, loop: ["elbow", "b"] }, { elbow: 0 }),
    /joint 'elbow' cannot be posed: pairs elbow, b close a loop/);
  assert.deepEqual(xbfPoseControls(kinematics), [{ id: "elbow", pair: "elbow", index: 0, label: "elbow", unit: "deg", min: -10, max: 120 }]);
});

test("a pair the engine kept with no value holds its links as built and refuses a pose by name", () => {
  const kinematics = xbfKinematics(STRUCTURE);
  const broken = { ...STRUCTURE, kinematics: { ...kinematics, asBuilt: {}, warnings: ["joint 'elbow' is kept with no value"],
    pairs: kinematics.pairs.map(pair => ({ ...pair, inconsistent: "hinge/arm is not where it can put it" })) } };
  const held = xbfKinematics(broken);
  assert.throws(() => xbfPoseValues(held, { elbow: 5 }), /joint 'elbow' cannot be posed: hinge\/arm is not where it can put it/);
  assert.deepEqual(xbfPoseControls(held), []);
  near(place(xbfPosedMatrices(broken, xbfPoseValues(held))[ARM], [120, 10, 10]), armTip(30), "the arm as built");
  assert.deepEqual(xbfOtherWarnings(held), []);
});

test("a structure the engine served posed is posed from where it stands", () => {
  // The engine's posed structure: the arm's matrix at 90, and `kinematics.pose` saying so.
  const kinematics = xbfKinematics(STRUCTURE);
  const raised = xbfPosedMatrices(STRUCTURE, { elbow: [90] });
  const posed = { ...STRUCTURE, instances: STRUCTURE.instances.map((instance, at) => ({ ...instance, matrix: raised[at] })),
    kinematics: { ...kinematics, pose: { values: { elbow: 90 }, configuration: "raised" } } };
  near(place(xbfPosedMatrices(posed, { elbow: [0] })[ARM], [120, 10, 10]), armTip(0), "from the served pose");
});

test("the scene moves an instance's group to the pose, and its element's matrix with it", () => {
  const parts = new Map(STRUCTURE.prototypes.map((prototype) => {
    const file = fs.readFileSync(path.join(FIXTURE, `${prototype.key}.xbm`));
    const mesh = readXbmPart(file.buffer.slice(file.byteOffset, file.byteOffset + file.byteLength));
    const held = new Map();
    return [prototype.key, { key: prototype.key, mesh, unmeshed: xbmUnmeshedFaces(mesh), retain() { return this; }, release() {},
      hold(name, make) { if (!held.has(name)) held.set(name, make()); return held.get(name); } }];
  }));
  const scene = createXbfScene(THREE, { structure: STRUCTURE, parts, version: "1-1" });
  assert.ok(scene.kinematics);
  scene.setPose({ elbow: [90] });
  const group = scene.object3D.children[ARM].children[0];
  near(place(group.matrixWorld.elements, [120, 10, 10]), armTip(90), "the arm's group");
  near(place(scene.describeElement("i1/face/1").matrix, [120, 10, 10]), armTip(90), "the element's matrix");
  assert.deepEqual(scene.object3D.children[0].children[0].matrix.elements, STRUCTURE.instances[0].matrix);
  scene.setPose(null);
  assert.deepEqual(scene.describeElement("i1/face/1").matrix, STRUCTURE.instances[ARM].matrix);
  scene.dispose();
});
